const fs = require(\"node:fs\");
const crypto = require(\"node:crypto\");
const root = \"publication/cases/split\";
const state = JSON.parse(fs.readFileSync("'`${root}/state.json`, "utf8"));
const manifest = JSON.parse(fs.readFileSync(`${root}/evidence/split-manifest.json`, "utf8"));
const remote = JSON.parse(fs.readFileSync(`${root}/remote.json`, "utf8"));
const refs = [...remote.body.matchAll(/!'"\\[["'^'"\\]]*\\]\\((["'^)]+)'"\\)/g)].map((match) => match[1]);
if (remote.liveHead "'!== state.demonstratedHead) throw new Error("live head differs from demonstrated head");
if (remote.headAtEdit !== state.demonstratedHead) throw new Error("head changed at edit");
if (remote.operations.length !== 1 || remote.operations[0].attachments.length !== 2) throw new Error("expected one two-part attachment operation");
if (refs.length !== 2) throw new Error(`expected 2 image references, received ${refs.length}`);
for (let index = 0; index < 2; index += 1) {
  const part = manifest.parts[index];
  const upload = remote.uploads[index];
  const bytes = fs.readFileSync(part.path);
  const sha256 = crypto.createHash("sha256").update(bytes).digest("hex");
  if (bytes.length !== part.bytes || sha256 !== part.sha256) throw new Error(`part ${index + 1} metadata mismatch`);
  if (upload.path !== part.path || upload.order !== index + 1) throw new Error(`upload ${index + 1} order mismatch`);
  if (refs[index] !== upload.url) throw new Error(`body reference ${index + 1} mismatch`);
  if (remote.body.includes(part.path)) throw new Error(`body retains local reference for part ${index + 1}`);
}
console.log(JSON.stringify({ liveHead: remote.liveHead, demonstratedHead: state.demonstratedHead, imageReferences: refs, uploadOrder: remote.uploads.map(({ order, path }) => ({ order, path })), verified: true }, null, 2));
